"""Two ERD sheets avoid hidden connections through unrelated entity boxes."""
def build(node,edge,render):
    ns=[node('customer',50,180,420,160,['E01 Customer','PK customer_id','type / verified attributes','FK segment_id? (sheet 2)'],'entity'),node('ap',700,180,420,160,['E04 AgreementParty','PK agreement+customer+role+from','FK customer_id / agreement_id','role / authority / interval'],'entity'),node('agreement',1350,180,420,160,['E03 Agreement','PK agreement_id','FK product_id / tariff_id','status / master_system'],'entity'),node('product',2000,180,420,160,['E10 Product','PK product_id','family / version'],'entity'),node('case',50,650,420,160,['E14 Case','PK case_id','FK customer_id / agreement_id?','channel / status'],'entity'),node('account',700,650,420,160,['E05 Account','PK account_id','FK agreement_id / branch_id','currency / number_token'],'entity'),node('tariff',1350,650,420,160,['E11 Tariff','PK tariff_id','FK product_id','rules / valid_from,to'],'entity'),node('branch',2000,650,420,160,['E12 Branch','PK branch_id','bank / code / interval'],'entity'),node('payment',50,1120,420,160,['E09 Payment','PK payment_id','FK debtor_account_id','amount / currency / status'],'entity'),node('posting',700,1120,420,180,['E08 Posting','PK posting_id (+ source scope)','FK account_id / payment_id?','ledger_tx / dc / amount','reversal_of? self FK'],'entity')]
    es=[edge('ap','customer',[(700,260),(470,260)],'Customer\n0..N roles',(500,200)),edge('ap','agreement',[(1120,260),(1350,260)],'Agreement\n1..N roles*',(1150,200)),edge('agreement','product',[(1770,260),(2000,260)],'Product\n0..N agreements',(1800,200)),edge('agreement','tariff',[(1560,340),(1560,650)],'Tariff\n0..N agreements',(1580,470)),edge('tariff','product',[(1770,690),(1880,690),(1880,300),(2000,300)],'Product\n0..N tariffs',(1900,500)),edge('account','agreement',[(1120,690),(1240,690),(1240,300),(1350,300)],'Agreement\n0..N accounts',(1150,500)),edge('account','branch',[(910,810),(910,930),(2210,930),(2210,810)],'Branch 0..N accounts',(1700,950)),edge('posting','account',[(910,1120),(910,810)],'Account\n0..N postings',(930,1040)),edge('payment','account',[(470,1190),(590,1190),(590,740),(700,740)],'Account\n0..N payments',(495,950)),edge('posting','payment',[(700,1230),(470,1230)],'Payment\n0..N postings',(500,1250)),edge('case','customer',[(260,650),(260,340)],'Customer\n0..N cases',(280,470)),edge('case','agreement',[(470,700),(530,700),(530,410),(1460,410),(1460,340)],'Agreement 0..N cases; nullable FK',(750,375)),edge('posting','posting',[(1120,1160),(1240,1160),(1240,1340),(1040,1340),(1040,1300)],'reversal_of?\n0..N reversals',(1260,1200))]
    render('Task1','logical-model','ERD 1/2 | Клиенты, договоры и финансовые данные','Стрелка FK → родитель. Подпись = число дочерних записей на родителя. ? = nullable FK.',ns,es,2500,1520,['* Active Agreement имеет 1..N участников, draft допускает 0. Все source keys сохраняют source_system.','Лист 2 дополняет модель шестью сущностями: Identifier, Segment, Card, Loan, Consent и Document.'])
    ns=[];es=[]
    groups=[
      ('identifier',['E02 Identifier','PK source+local_id+from','FK customer_id','match / history'], [('customer','E01 Customer','PK customer_id','0..N IDs / Customer')]),
      ('customer2',['E01 Customer (повтор)','PK customer_id','FK segment_id?'], [('segment','E13 Segment','PK segment_id; definition/version','0..1 segment / Customer')]),
      ('card',['E06 Card','PK card_id','FK account / agreement / holder','pan_token / status'], [('account','E05 Account','PK account_id','0..N cards / Account'),('agreement','E03 Agreement','PK agreement_id','0..N cards / Agreement'),('customer','E01 Customer','PK customer_id','0..N cards / Holder')]),
      ('loan',['E07 Loan','PK loan_id','FK agreement UNIQUE / account','schedule / principal'], [('agreement','E03 Agreement','PK agreement_id','0..1 loan / Agreement'),('account','E05 Account','PK account_id','0..N loans / Account')]),
      ('consent',['E15 Consent','PK consent_id','FK customer_id','purpose / scope / evidence'], [('customer','E01 Customer','PK customer_id','0..N consents / Customer')]),
      ('document',['E16 Document','PK document_id','FK customer? / agreement?','object_key / hash / retention'], [('customer','E01 Customer','PK customer_id','0..N docs / Customer'),('agreement','E03 Agreement','PK agreement_id','0..N docs / Agreement')])]
    for i,(key,lines,parents) in enumerate(groups):
        x=40+(i%2)*1300;y=170+(i//2)*500
        ns.append(node(key,x,y+80,420,200,lines,'entity'))
        for j,(pk,title,attrs,label) in enumerate(parents):
            parent_key=f'{key}_{pk}';py=y+j*140
            ns.append(node(parent_key,x+800,py,390,100,[title+' (повтор)',attrs],'entity'))
            sy=y+130+j*50;tx=x+800;ty=py+50
            es.append(edge(key,parent_key,[(x+420,sy),(x+730,sy),(x+730,ty),(tx,ty)],label,(x+450,py+10)))
    render('Task1','logical-support','ERD 2/2 | Идентичность и продуктовые/документные связи','Повторяющиеся родительские узлы обозначают те же сущности листа 1. Стрелка FK → PK.',ns,es,2600,1710,['Обязательность FK указана в дочерней сущности. Document требует хотя бы одну ссылку: customer или agreement.','Identifier — history crosswalk; один current source key не может указывать на двух Customer.'])
